import{_ as t,o,c as a,a0 as n}from"./chunks/framework.iBgbCoJu.js";const p=JSON.parse('{"title":"Frontend (client-ui)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/frontend/index.md","filePath":"reference/frontend/index.md"}'),s={name:"reference/frontend/index.md"};function i(r,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="frontend-client-ui" tabindex="-1">Frontend (client-ui) <a class="header-anchor" href="#frontend-client-ui" aria-label="Permalink to &quot;Frontend (client-ui)&quot;">​</a></h1><p>The frontend is a Nuxt 4 SSR web application that provides the user interface for managing projects, analyses, nodes, and platform administration.</p><h2 id="running" tabindex="-1">Running <a class="header-anchor" href="#running" aria-label="Permalink to &quot;Running&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Development (from repo root)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client-ui</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> privateaim/hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui</span></span></code></pre></div><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><strong>Core API</strong> — REST API for all domain operations</li><li><strong>Authup</strong> — OAuth2 identity provider (login, registration, permissions)</li></ul><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>NUXT_PUBLIC_CORE_URL</code></td><td>—</td><td>Core API base URL</td></tr><tr><td><code>NUXT_PUBLIC_AUTHUP_URL</code></td><td>—</td><td>Authup URL</td></tr><tr><td><code>NUXT_PUBLIC_AUTHUP_CLIENT_ID</code></td><td><code>admin-console</code></td><td>OAuth2 client used for the login (authorization-code) flow</td></tr><tr><td><code>NUXT_PUBLIC_ACCOUNT_URL</code></td><td><code>&lt;NUXT_PUBLIC_AUTHUP_URL&gt;/account</code></td><td>Authup account console, linked from the &quot;Account&quot; sidebar entry</td></tr><tr><td><code>NUXT_PUBLIC_STORAGE_URL</code></td><td>—</td><td>Storage service URL</td></tr><tr><td><code>NUXT_PUBLIC_TELEMETRY_URL</code></td><td>—</td><td>Telemetry service URL</td></tr><tr><td><code>NUXT_PUBLIC_COOKIE_DOMAIN</code></td><td>— (host-only)</td><td><code>Domain</code> attribute for the session cookies. Leave empty unless a sibling host must read them — see <a href="#session-cookies">Session cookies</a></td></tr><tr><td><code>NUXT_PUBLIC_MESSENGER_URL</code></td><td>—</td><td>Messenger service URL</td></tr></tbody></table><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>The UI signs in with the <strong>OAuth2 Authorization Code flow (PKCE)</strong> — credentials are never entered in the Hub UI itself. On the login page the user picks a <strong>realm</strong> (<code>ARealmGrid</code>, which reveals a search field once more than 8 realms exist); the app then builds an authorize URL and redirects to Authup&#39;s <code>/authorize</code> endpoint, where the login form and configured identity providers live. Authup redirects back to <code>&lt;ui-origin&gt;/login/callback</code>, and the <code>@authup/client-web-nuxt</code> routing interceptor exchanges the authorization code for a session.</p><p>When the user was sent to the login page from a deep link, the post-login destination rides in the callback URI&#39;s <strong>own query</strong> (<code>&lt;ui-origin&gt;/login/callback?redirect=%2Fprojects</code>), so the authorization server carries it back and the interceptor navigates there after the exchange. The same string is replayed byte-for-byte at the <code>/token</code> exchange (RFC 6749 §4.1.3).</p><p>The OAuth client is configurable via <code>NUXT_PUBLIC_AUTHUP_CLIENT_ID</code> (default: <code>admin-console</code>, an Authup built-in client provisioned for every realm). The configured client <strong>must</strong> register <code>&lt;ui-origin&gt;/login/callback**</code> as an allowed redirect URI — note the trailing <code>**</code>. A <code>&lt;ui-origin&gt;/**</code> pattern (what <code>TRUSTED_ORIGINS</code> generates) covers it as well.</p><div class="warning custom-block"><p class="custom-block-title">Upgrading to Authup &gt;= 1.0.0-beta.63</p><p>An <strong>exact</strong> <code>&lt;ui-origin&gt;/login/callback</code> registration is no longer sufficient. The post-login destination now travels in the callback URI&#39;s query, and Authup matches a redirect URI against the full canonical URL <strong>including</strong> its query string (<code>isSimpleURLMatch</code>). A deep-link login against an exactly-registered client is refused at the authorize step, while a login from the bare login page still succeeds — so the breakage looks intermittent.</p><p>Widen the client&#39;s <code>redirectUri</code> (a comma-separated glob list, where <code>*</code> stays inside a path segment and <code>**</code> matches the rest) to <code>&lt;ui-origin&gt;/login/callback**</code> before upgrading.</p></div><div class="warning custom-block"><p class="custom-block-title">Upgrading from Authup &lt; 1.0.0-beta.59</p><p>Authup beta.59 removed the shared <code>web</code> system client that used to be provisioned for every realm (<a href="https://github.com/authup/authup/pull/3379" target="_blank" rel="noreferrer">authup#3379</a>). Existing <code>web</code> rows survive and keep working, but they no longer track <code>PUBLIC_URL</code> / <code>TRUSTED_ORIGINS</code> changes, and realms created after the upgrade get no <code>web</code> client at all — which is why the default moved to <code>admin-console</code>.</p><p>A deployment serving the UI from its own origin should register a <strong>dedicated</strong> client (once per realm, e.g. via a wildcard <code>realms[]</code> provisioning entry named <code>&quot;*&quot;</code>) and point <code>NUXT_PUBLIC_AUTHUP_CLIENT_ID</code> at it, rather than sharing Authup&#39;s console client.</p></div><h2 id="session-cookies" tabindex="-1">Session cookies <a class="header-anchor" href="#session-cookies" aria-label="Permalink to &quot;Session cookies&quot;">​</a></h2><p>The UI persists its session in cookies at path <code>/</code>: <code>access_token</code>, <code>access_token_expire_date</code>, <code>refresh_token</code>, <code>id_token</code>, <code>realm</code> and <code>realm_management</code>. Authup&#39;s own hosted pages — the authorize/login pages and the account console — persist <strong>their</strong> session under the <em>same names</em>, because both sides run <code>@authup/client-web-kit</code>&#39;s store.</p><p>The two stay apart only while their <code>(name, domain, path)</code> cookie keys differ. When they collide, the browser keeps <strong>both</strong> records and sends both; a read takes the <strong>first</strong>, which is the <strong>older</strong> one. Each side can then hydrate, rotate and <code>cleanup()</code>-revoke the other&#39;s tokens. The symptom is being <strong>logged out on the next page reload</strong> — the login itself succeeds, because everything after the code exchange is still in memory.</p><p>Which deployment layout you run decides what is required:</p><table tabindex="0"><thead><tr><th>Authup is served at</th><th>Requirement</th></tr></thead><tbody><tr><td>A path on the UI&#39;s own origin (<code>https://hub.example.com/auth</code>)</td><td>Authup including <a href="https://github.com/authup/authup/issues/3495" target="_blank" rel="noreferrer">authup#3495</a>, which scopes the console cookies to that sub-path. <strong>Unreleased as of <code>1.0.0-beta.63</code></strong> — on beta.63 and earlier this layout is broken. Keep <code>NUXT_PUBLIC_COOKIE_DOMAIN</code> empty.</td></tr><tr><td>A subdomain of the UI host (<code>auth.hub.example.com</code>)</td><td><code>NUXT_PUBLIC_COOKIE_DOMAIN</code> must be empty, or at least not cover that host. A <code>Domain</code> value is delivered to every subdomain of itself, so it reaches Authup&#39;s origin and collides there.</td></tr><tr><td>A separate origin (<code>auth.example.com</code>, or any unrelated host)</td><td>Nothing. Separate cookie jars.</td></tr></tbody></table><p><strong>Rule: leave <code>NUXT_PUBLIC_COOKIE_DOMAIN</code> empty.</strong> Host-only cookies are correct in all three layouts. Set it only when a <em>sibling</em> host genuinely has to read the cookie itself, and never to a value that covers Authup&#39;s host. The Helm chart refuses that combination at render time (<code>flameHub.validateCookieDomain</code>).</p><p>It buys the Hub nothing by default: the services read the bearer token from the <code>Authorization</code> header, and their cookie fallback only ever sees same-origin requests under a shared hostname.</p><div class="warning custom-block"><p class="custom-block-title">Changing <code>NUXT_PUBLIC_COOKIE_DOMAIN</code> from a value to empty</p><p>The switch does not clear what browsers already hold. The previously written <code>Domain</code>-scoped records survive, they are <strong>older</strong> than the host-only ones written after the change, and they therefore keep winning the read — so a returning user can stay broken past the fix.</p><p><code>access_token</code> and <code>access_token_expire_date</code> carry a <code>maxAge</code> and lapse with the token, but <code>refresh_token</code>, <code>id_token</code>, <code>realm</code> and <code>realm_management</code> are session cookies: they live until the browser is closed. Have affected users close the browser once, or clear the site&#39;s cookies.</p></div><h2 id="server-rendering-and-hydration" tabindex="-1">Server Rendering and Hydration <a class="header-anchor" href="#server-rendering-and-hydration" aria-label="Permalink to &quot;Server Rendering and Hydration&quot;">​</a></h2><p>The app runs with <code>ssr: true</code>, but nothing fetched during the server render used to reach the browser. Every detail page issued its request <strong>twice</strong> — once while rendering the HTML, once again on the hydrating client. Every list was worse: its initial load ran in a detached microtask that resolved <em>after</em> the HTML had already been flushed, so the server paid for the request and still shipped an empty list, which the client then fetched again.</p><p>The handoff runs over <strong><code>@authup/client-web-kit</code>&#39;s hydration store</strong>, provided automatically by <code>@authup/client-web-nuxt</code>&#39;s kit plugin and backed by <code>nuxtApp.payload.data</code> — the same bucket <code>useAsyncData</code> transports its results in. Hub adds no install option and no plugin of its own: <code>@privateaim/client-vue</code> calls <code>injectHydrationStore()</code> and no-ops when it returns <code>undefined</code>. Under a host that provides no store the server render does not load at all, rather than rendering rows the hydrating client has no way to reproduce.</p><h3 id="lists" tabindex="-1">Lists <a class="header-anchor" href="#lists" aria-label="Permalink to &quot;Lists&quot;">​</a></h3><p><code>createList</code> records the initial load under <code>flame:list:&lt;type&gt;:&lt;useId()&gt;</code> during the server render; the hydrating client adopts that snapshot (<code>data</code>, <code>total</code>, <code>meta</code>) and skips its own load. The entry is consumed on read — a collection goes stale, and it must not seed a later client-side navigation back to the route.</p><p>The key is deliberately <strong>not</strong> derived from the query. A query-derived key has to be re-derived identically on the client, which makes filter insertion order, a <code>query</code> prop assembled from store state that is not populated yet on one side, and two same-query lists on one page all load-bearing — and each of them fails silently, as a list that simply fetches twice again. <code>useId()</code> (Vue 3.5) is stable across the server render and the hydrating client for the same position in the component tree, so agreement is structural instead of something a caller can get wrong. The entity type is in the key only to bound the blast radius of an entry that is recorded but never adopted.</p><p>That stability has one prerequisite, and it is easy to break by accident: <code>createList</code> registers its <code>onServerPrefetch</code> hook on <strong>both</strong> sides of the boundary, not just on the server. A non-empty <code>instance.sp</code> is what makes Vue call <code>markAsyncBoundary()</code> after setup, handing the component&#39;s subtree a fresh <code>useId</code> counter. Register the hook only when <code>isServerRuntime()</code> — the obvious reading — and the boundary exists only on the server, so any <code>useId()</code> drawn inside or after a list shifts between the two renders: the second list on a page then derives the key the server used for the <em>first</em> one and adopts the wrong rows, with its own load suppressed so it never corrects. The hook body never runs on the client — <code>@vue/server-renderer</code> is the only thing that invokes <code>sp</code> — so registering it there is free.</p><p>Because the list&#39;s rows now reach the payload, a <strong>collection query must not request a permission-gated column</strong>. <code>fields: [&#39;+accountSecret&#39;]</code> on the registry-projects list was dropped for exactly this reason: nothing on that page rendered it (the details modal re-resolves the record by id), and leaving it in would have written every Harbor robot secret into the served HTML document instead of an XHR response. Keep credential columns on the record read that displays them.</p><h3 id="two-rules-a-change-here-must-not-break" tabindex="-1">Two rules a change here must not break <a class="header-anchor" href="#two-rules-a-change-here-must-not-break" aria-label="Permalink to &quot;Two rules a change here must not break&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rule</th><th>If broken</th></tr></thead><tbody><tr><td>Never record a failed or coalesced-away load.</td><td>An adopted snapshot suppresses the client&#39;s own load, so an empty snapshot strands the list on it with no retry. <code>createListRaw</code>&#39;s <code>loaded</code> flag enforces it — only a load that ran to completion is recorded.</td></tr><tr><td>Pass <code>deep: true</code> to <code>useAsyncData</code>.</td><td>Nuxt 4 returns a <code>shallowRef</code>, and every detail page updates its entity <strong>per property</strong> (<code>updateObjectProperties</code> / <code>extendObject</code>). Without it the page silently stops updating after a save. The <code>useEntityRecord</code> composable centralises this.</td></tr></tbody></table><p>Never give an authenticated route an <code>swr</code> or <code>isr</code> route rule — the payload is per-request (<code>nuxt.config.ts</code> declares exactly one route rule, <code>&#39;/login/callback&#39;: { ssr: false }</code>).</p><h3 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><p>The server render now <strong>waits</strong> for a list&#39;s request (<code>onServerPrefetch</code>) where it previously did not, so a list&#39;s upstream latency sits on the SSR critical path. The nine <code>[id].vue</code> detail pages already blocked the render this way — they <code>await</code> their record in <code>setup()</code> — so this is not a new class of dependency, but a slow Core API now shows up as time-to-first-byte rather than as a spinner.</p><p>List rows now render on the server, which puts <code>&lt;VCTimeago&gt;</code> on both sides of the boundary for the first time. It computes a wall-clock-relative string during <code>setup()</code>, so a row whose age crosses a bucket boundary between the render and the hydration — or plain client/server clock skew — produces a text mismatch, and Vue reports those through <code>console.error</code> in production builds too. Vue repairs the text, so nothing is misrendered, but it is a new source of console noise on list pages and it makes a <em>real</em> mismatch harder to spot. Giving <code>VCTimeago</code> an SSR-stable first render belongs upstream in <code>@vuecs/timeago</code>; until then, treat a lone timeago mismatch as expected.</p><p>Records resolved by <code>createEntityManager</code> are <strong>not</strong> handed over yet; those still fetch on both sides of the boundary. Tracked as a follow-up.</p><h2 id="account-self-service" tabindex="-1">Account Self-Service <a class="header-anchor" href="#account-self-service" aria-label="Permalink to &quot;Account Self-Service&quot;">​</a></h2><p>The UI has <strong>no settings area of its own</strong>. Profile, password, authenticators, sessions and connected applications live in <strong>Authup&#39;s account console</strong>, served by Authup&#39;s server-core on the IdP origin as of <code>v1.0.0-beta.59</code>. Keeping a second, thinner surface in the UI would only split the account UX across two origins.</p><p>The header&#39;s account icon links straight at <code>&lt;NUXT_PUBLIC_ACCOUNT_URL&gt;/?ref=&lt;ui-origin&gt;&amp;realmId=&lt;session-realm&gt;</code>, defaulting to <code>&lt;NUXT_PUBLIC_AUTHUP_URL&gt;/account</code>. It is the only entry point — the sidebar carries no account entry, so the one link that leaves for the IdP origin sits in one place rather than two. The console renders the <code>ref</code> origin as a back link after validating it against the trusted app origins; the UI origin is already required to be trusted for the login callback, so this needs no extra deployment configuration. Set <code>NUXT_PUBLIC_ACCOUNT_URL</code> for deployments where the console is not reachable under <code>&lt;NUXT_PUBLIC_AUTHUP_URL&gt;/account</code>.</p><p><code>realmId</code> is a safety net for the session mismatch between the two origins: the UI&#39;s session outlives the IdP&#39;s, so the account icon still renders after the IdP session has expired. The console applies the hint only when it sees an unauthenticated visitor, and then starts the authorization-code flow against that realm instead of asking which realm to sign in to — a question the visitor was never asked when signing into the UI. It is ignored while a console session exists, and while the console carries an <code>error</code> param, so a denied consent cannot loop back into the flow.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Project management</strong> — create and manage collaborative research projects</li><li><strong>Analysis workflows</strong> — define, configure, and monitor distributed analyses</li><li><strong>Node management</strong> — register and manage compute nodes</li><li><strong>Administration</strong> — realm management, user roles, approval workflows</li><li><strong>Real-time updates</strong> — live status via WebSocket (Messenger service)</li><li><strong>Light / dark mode</strong> — class-based color mode with a header toggle</li></ul><h2 id="technology" tabindex="-1">Technology <a class="header-anchor" href="#technology" aria-label="Permalink to &quot;Technology&quot;">​</a></h2><ul><li><strong>Nuxt 4</strong> with SSR</li><li><strong>Vue 3</strong> composition API</li><li><strong>Tailwind CSS v4</strong> via <strong>@privateaim/client-vue-theme</strong> — design tokens, light/dark chrome, card system</li><li><strong>@vuecs/*</strong> component framework + <strong>Iconify</strong> SVG icons</li><li><strong>@privateaim/client-vue</strong> — shared component library</li><li><strong>@privateaim/core-http-kit</strong> — typed HTTP client for Core API</li><li><strong>Authup client libraries</strong> — authentication and authorization UI</li></ul><h2 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Icons&quot;">​</a></h2><p>The client ships only the icons it actually renders. <code>@nuxt/icon</code>&#39;s standalone vite plugin scans source for <code>&lt;collection&gt;:&lt;name&gt;</code> literals at build time and emits just that subset into <code>virtual:nuxt-icon-bundle/register</code>, which <code>plugins/vuecs.ts</code> imports. Registration goes through <code>addIcon</code> from <code>@iconify/vue</code> — the same global store <code>&lt;VCIcon&gt;</code> reads — so components are unaffected. This replaced registering the full Font Awesome 6 solid + brands collections (1,902 icons, ~429 KB gzip) and cut the client JS payload from ~1,031 KB to ~623 KB gzip.</p><p>The scanned paths are configured in <code>apps/client-ui/icon-bundle.config.ts</code>. They cover this app, <code>@privateaim/client-vue</code>, <code>@privateaim/client-vue-theme</code>, <code>@authup/client-web-kit</code> and <code>@vuecs/icons-font-awesome</code> (whose preset holds the vuecs behavioral defaults — pagination arrows, submit-button, alert and collapse icons — that appear in no hub source file).</p><p>Two consequences for anyone adding an icon:</p><ul><li><strong>Write the icon name as a literal.</strong> A composed name (<code>\`fa6-brands:\${os}\`</code>) is invisible to the scan, so it is never bundled; <code>@iconify/vue</code> then falls back to fetching it from the public Iconify API at runtime. Resolve to literals instead — see <code>FAnalysisBuildStep.vue</code>.</li><li><strong>A path that stops matching fails silently</strong> — an empty icon slot, not a build error. <code>apps/client-ui/test/unit/icon-bundle.spec.ts</code> pins one uniquely-attributable icon per scanned source to catch that.</li></ul>`,50)])])}const g=t(s,[["render",i]]);export{p as __pageData,g as default};
